window.RP_SESSION={"id":"S-5b2137084350","messages":[{"id":"RP-III-0141567","time":"2026-08-11T17:30:00+09:00","room":"RP III","name":"오즈발드 윌 / 클레이·주점 손님","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"다시 어젯밤, 가델랏 허그와 뻬르난떼가 ‘전설적인 길드’와 인연을 맺은 그날…","characters":["P-d40bea4fdee0"]},{"id":"RP-III-0141568","time":"2026-08-11T17:31:00+09:00","room":"RP III","name":"오즈발드 윌 / 클레이·주점 손님","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"오즈는 주점의 손님들에게 약간의 술값을 각각 보태어, 여러 자리를 오가며 골기아의 장소에 대한 정보를 여럿 얻었다.","characters":["P-d40bea4fdee0"]},{"id":"RP-III-0141569","time":"2026-08-11T17:32:00+09:00","room":"RP III","name":"오즈발드 윌 / 클레이·주점 손님","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"흥미롭거나 관심이 생긴 내용들을 수첩에 적은 뒤, 오즈는 주점을 나서고 그 장소들을 하나하나씩 방문해본다.","characters":["P-d40bea4fdee0"]},{"id":"RP-III-0141570","time":"2026-08-11T17:33:00+09:00","room":"RP III","name":"오즈발드 윌 / 클레이·주점 손님","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"첫번째로 들른 곳은 골기아의 시내에 위치한 한 분수였다.","characters":["P-d40bea4fdee0"]},{"id":"RP-III-0141571","time":"2026-08-11T17:35:00+09:00","room":"RP III","name":"오즈발드 윌 / 클레이·주점 손님","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"몇 미터쯤 떨어진 거리에 자그마한 마법 공방이 위치해 있고, 지붕이 매력적인 작은 건물들이 시내에서 뻗어진 길을 따라 일렬로 이어진다.","characters":["P-d40bea4fdee0"]},{"id":"RP-III-0141572","time":"2026-08-11T17:35:00+09:00","room":"RP III","name":"오즈발드 윌 / 클레이·주점 손님","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"분명 주점에서 어떤 한 사내에게 들은 바로는…","characters":["P-d40bea4fdee0"]},{"id":"RP-III-0141573","time":"2026-08-11T17:36:00+09:00","room":"RP III","name":"오즈발드 윌 / 클레이·주점 손님","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“”말도 마, 얼마전에 분수대 쪽에서 커어다란 폭발음이 들리길래 자릴 박차고 동료들과 시내로 나가봤었는데 말이야, 글쎄 마법 공방 건물이 송두리째 뽑혀 날아가 분수를 와그작- 하고 뭉게버렸었다니까?“”","characters":["P-d40bea4fdee0"]},{"id":"RP-III-0141574","time":"2026-08-11T17:37:00+09:00","room":"RP III","name":"오즈발드 윌 / 클레이·주점 손님","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”“듣기로는 어설픈 용맹? 거기 길드의 사람 둘이서 도둑을 하나 잡으려다 벌인 짓이라던데… 도대체 뭐하는 곳인거야 거긴?”“","characters":["P-d40bea4fdee0"]},{"id":"RP-III-0141575","time":"2026-08-11T17:39:00+09:00","room":"RP III","name":"오즈발드 윌 / 클레이·주점 손님","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”“아무튼 형씨도 조심해, 순하게 생겨서는 그런 무서운 곳에 실수로 발을 들여버릴지도 모르니깐 말이야.”“\n\n”“아하잇, 게럴드! 넌 아까부터 거기에 못하는 말이 없어!”“\n\n”“크헴헴, 농담인거 알잖아!”“","characters":["P-d40bea4fdee0"]},{"id":"RP-III-0141576","time":"2026-08-11T17:40:00+09:00","room":"RP III","name":"오즈발드 윌 / 클레이·주점 손님","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“크흠… 그럼, 시간 들여 대화에 응해주셔서 감사드립니다. 저는 이만…“","characters":["P-d40bea4fdee0"]},{"id":"RP-III-0141577","time":"2026-08-11T17:41:00+09:00","room":"RP III","name":"오즈발드 윌 / 클레이·주점 손님","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"도대체 자신이 있는 이곳은 뭐하는 곳일까, 하는 생각이 스멀스멀 피어오르는 오즈였다.\n아무튼, 오즈는 지금 그 분수대에 다다른 것이다.","characters":["P-d40bea4fdee0"]},{"id":"RP-III-0141578","time":"2026-08-11T17:42:00+09:00","room":"RP III","name":"오즈발드 윌 / 클레이·주점 손님","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"다행히도, 빠른 시일 내에 수리가 끝난것인지, 분수대는 곤죽이 되었다는 말과는 다르게 유유히 물을 흘려내고 있었고, 마법 공방 또한 그날의 사건 이후 손님이 늘어 제법 북적북적한 분위기를 띄고 있는 듯 했다.","characters":["P-d40bea4fdee0"]},{"id":"RP-III-0141579","time":"2026-08-11T17:44:00+09:00","room":"RP III","name":"오즈발드 윌 / 클레이·주점 손님","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”음… 그러니까 저희 길드의 길드원 분들께서…\n…저만한 마법 공방 하나를 통째로 날려버리셨다는 것입니까…“","characters":["P-d40bea4fdee0"]},{"id":"RP-III-0141580","time":"2026-08-11T17:45:00+09:00","room":"RP III","name":"오즈발드 윌 / 클레이·주점 손님","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"오즈는 자기도 모르게 미간에 손을 슬쩍 짚었다.\n누구인지는 모르겠지만, 그 둘은 가능한 만나지 말자. 괜한 짓을 했다간 휘말려버릴지도 모르니 말이다…","characters":["P-d40bea4fdee0"]},{"id":"RP-III-0141581","time":"2026-08-11T17:47:00+09:00","room":"RP III","name":"오즈발드 윌 / 클레이·주점 손님","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”잡다한 생각은 이쯤에서 끝내죠.\n오늘 이곳을 찾아온 이유는 단지 지도를 그리기 위해 와본 것이니 말입니다.“","characters":["P-d40bea4fdee0"]},{"id":"RP-III-0141582","time":"2026-08-11T17:48:00+09:00","room":"RP III","name":"오즈발드 윌 / 클레이·주점 손님","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"오즈발드는 수첩을 펼치고, 자신이 걸어온 지붕이 늘어진 거리와 눈앞의 분수대, 그리고 은은한 빛이 세어나오는 공방을 순서로, 차근차근 페이지를 넘겨가며 지도의 부분을 그려나가기 시작했다.","characters":["P-d40bea4fdee0"]},{"id":"RP-III-0141583","time":"2026-08-11T17:50:00+09:00","room":"RP III","name":"오즈발드 윌 / 클레이·주점 손님","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"[ 오즈, 자리를 옮기는게 어떨까 하는데요.\n아까부터 지나가는 인파에 조금씩 부딪히고 있잖아요? 이러면 지도를 그리기에도 어려울거라구요. ]","characters":["P-d40bea4fdee0"]},{"id":"RP-III-0141584","time":"2026-08-11T17:50:00+09:00","room":"RP III","name":"오즈발드 윌 / 클레이·주점 손님","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"이모티콘","characters":["P-d40bea4fdee0"]},{"id":"RP-III-0141585","time":"2026-08-11T17:53:00+09:00","room":"RP III","name":"오즈발드 윌 / 클레이·주점 손님","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“하하, 그렇지만 클레이 님, 지금 이곳에서 이러한 구도로 그려내야, 분수대와 공방을 한꺼번에 잡을 수 있을 것 같아 그렇습니다.\n자세한 부분은 이후 가까이서 하나하나 그려나갈 것이니, 지금은 이것에 집중해보도록 하겠습니다.“","characters":["P-d40bea4fdee0"]},{"id":"RP-III-0141586","time":"2026-08-11T17:54:00+09:00","room":"RP III","name":"오즈발드 윌 / 클레이·주점 손님","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"!의지","characters":["P-d40bea4fdee0"]},{"id":"RP-III-0141587","time":"2026-08-11T17:54:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'오즈발드 윌'의 의지 판정 :\n[5] + [2] = [7]\n결과 : 쓰라린 실패, 운명을 빗겨갈 순 없습니다.","characters":[]},{"id":"RP-III-0141588","time":"2026-08-11T17:55:00+09:00","room":"RP III","name":"오즈발드 윌 / 클레이·주점 손님","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"툭-","characters":["P-d40bea4fdee0"]},{"id":"RP-III-0141589","time":"2026-08-11T17:55:00+09:00","room":"RP III","name":"오즈발드 윌 / 클레이·주점 손님","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"부욱-","characters":["P-d40bea4fdee0"]},{"id":"RP-III-0141590","time":"2026-08-11T17:55:00+09:00","room":"RP III","name":"오즈발드 윌 / 클레이·주점 손님","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“음?”","characters":["P-d40bea4fdee0"]},{"id":"RP-III-0141591","time":"2026-08-11T17:55:00+09:00","room":"RP III","name":"오즈발드 윌 / 클레이·주점 손님","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“이런, 역시나…”","characters":["P-d40bea4fdee0"]},{"id":"RP-III-0141592","time":"2026-08-11T17:56:00+09:00","room":"RP III","name":"오즈발드 윌 / 클레이·주점 손님","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"[ 내가 뭐랬어요, 분명 그리기 어려울거라고 했었죠? 그냥 저쪽에서 편하게 하나하나 그려나가자구요. 조금 오래 걸리면 뭐 어때요? ]","characters":["P-d40bea4fdee0"]},{"id":"RP-III-0141593","time":"2026-08-11T17:57:00+09:00","room":"RP III","name":"오즈발드 윌 / 클레이·주점 손님","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“크흠, 그렇다면 클레이 님의 말씀대로, 자리를 옮겨서 다시 그려보아야겠습니다...“","characters":["P-d40bea4fdee0"]},{"id":"RP-III-0141594","time":"2026-08-11T17:58:00+09:00","room":"RP III","name":"오즈발드 윌 / 클레이·주점 손님","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"그렇게 오즈는 지나가는 인파 건너로, 분수대를 힐끔 힐끔 올려다 보며, 어렵사리 시내의 지도 부분을 그려내는것을 마쳤다고.","characters":["P-d40bea4fdee0"]},{"id":"RP-III-0141595","time":"2026-08-11T17:58:00+09:00","room":"RP III","name":"오즈발드 윌 / 클레이·주점 손님","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-d40bea4fdee0"]},{"id":"RP-III-0141596","time":"2026-08-11T17:59:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"-fin","characters":[]}]};
